CREATE TABLE registration_email_claims(email TEXT PRIMARY KEY COLLATE NOCASE,application_id TEXT REFERENCES applications(id),student_id TEXT REFERENCES students(id),claimed_at TEXT NOT NULL);
INSERT OR IGNORE INTO registration_email_claims SELECT lower(trim(email)),id,student_id,created_at FROM applications WHERE trim(email)<>'' ORDER BY created_at,id;
INSERT OR IGNORE INTO registration_email_claims SELECT lower(trim(guardian_email)),id,student_id,created_at FROM applications WHERE registration_category='kids' AND contact_recipient='guardian' AND trim(guardian_email)<>'' ORDER BY created_at,id;
INSERT OR IGNORE INTO registration_email_claims SELECT lower(trim(email)),NULL,id,created_at FROM students WHERE trim(email)<>'' ORDER BY created_at,id;
CREATE TABLE duplicate_registration_review(id INTEGER PRIMARY KEY AUTOINCREMENT,email TEXT NOT NULL,reason TEXT NOT NULL,created_at TEXT NOT NULL);
INSERT INTO duplicate_registration_review(email,reason,created_at) SELECT email,'Existing registrations share this email. Records are preserved; use one current registration for future class changes.',strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM (SELECT lower(trim(email)) email,id FROM applications WHERE trim(email)<>'' UNION SELECT lower(trim(guardian_email)),id FROM applications WHERE registration_category='kids' AND contact_recipient='guardian' AND trim(guardian_email)<>'') GROUP BY email HAVING COUNT(*)>1;
CREATE TRIGGER registration_email_unique_insert BEFORE INSERT ON applications WHEN (trim(NEW.email)<>'' AND EXISTS(SELECT 1 FROM registration_email_claims WHERE email=lower(trim(NEW.email)))) OR (NEW.registration_category='kids' AND NEW.contact_recipient='guardian' AND trim(NEW.guardian_email)<>'' AND EXISTS(SELECT 1 FROM registration_email_claims WHERE email=lower(trim(NEW.guardian_email)))) BEGIN SELECT RAISE(ABORT,'An email address can register only once'); END;
CREATE TRIGGER registration_email_claim_insert AFTER INSERT ON applications BEGIN INSERT OR IGNORE INTO registration_email_claims SELECT lower(trim(NEW.email)),NEW.id,NEW.student_id,NEW.created_at WHERE trim(NEW.email)<>''; INSERT OR IGNORE INTO registration_email_claims SELECT lower(trim(NEW.guardian_email)),NEW.id,NEW.student_id,NEW.created_at WHERE NEW.registration_category='kids' AND NEW.contact_recipient='guardian' AND trim(NEW.guardian_email)<>''; END;
CREATE TRIGGER registration_email_unique_update BEFORE UPDATE ON applications WHEN (lower(trim(NEW.email))<>lower(trim(OLD.email)) AND trim(NEW.email)<>'' AND EXISTS(SELECT 1 FROM registration_email_claims WHERE email=lower(trim(NEW.email)) AND application_id IS NOT NEW.id AND (student_id IS NULL OR student_id IS NOT NEW.student_id))) OR ((lower(trim(NEW.guardian_email))<>lower(trim(OLD.guardian_email)) OR NEW.contact_recipient<>OLD.contact_recipient) AND NEW.registration_category='kids' AND NEW.contact_recipient='guardian' AND trim(NEW.guardian_email)<>'' AND EXISTS(SELECT 1 FROM registration_email_claims WHERE email=lower(trim(NEW.guardian_email)) AND application_id IS NOT NEW.id AND (student_id IS NULL OR student_id IS NOT NEW.student_id))) BEGIN SELECT RAISE(ABORT,'An email address can register only once'); END;
CREATE TRIGGER registration_email_claim_update AFTER UPDATE ON applications BEGIN INSERT OR IGNORE INTO registration_email_claims SELECT lower(trim(NEW.email)),NEW.id,NEW.student_id,NEW.updated_at WHERE trim(NEW.email)<>''; INSERT OR IGNORE INTO registration_email_claims SELECT lower(trim(NEW.guardian_email)),NEW.id,NEW.student_id,NEW.updated_at WHERE NEW.registration_category='kids' AND NEW.contact_recipient='guardian' AND trim(NEW.guardian_email)<>''; UPDATE registration_email_claims SET student_id=NEW.student_id WHERE application_id=NEW.id; END;
CREATE TRIGGER single_student_enrollment BEFORE INSERT ON enrollments WHEN EXISTS(SELECT 1 FROM enrollments WHERE student_id=NEW.student_id AND application_id<>NEW.application_id) BEGIN SELECT RAISE(ABORT,'A student may have only one registration; edit the existing class'); END;
CREATE TRIGGER single_linked_registration BEFORE INSERT ON applications WHEN NEW.existing_student_id IS NOT NULL AND (EXISTS(SELECT 1 FROM applications WHERE student_id=NEW.existing_student_id OR existing_student_id=NEW.existing_student_id) OR EXISTS(SELECT 1 FROM enrollments WHERE student_id=NEW.existing_student_id)) BEGIN SELECT RAISE(ABORT,'A student may have only one registration; edit the existing class'); END;
CREATE TRIGGER student_contact_unique BEFORE UPDATE OF email ON students WHEN lower(trim(NEW.email))<>lower(trim(OLD.email)) AND trim(NEW.email)<>'' AND EXISTS(SELECT 1 FROM registration_email_claims c WHERE c.email=lower(trim(NEW.email)) AND c.student_id IS NOT NEW.id AND NOT EXISTS(SELECT 1 FROM applications a WHERE a.id=c.application_id AND (a.student_id=NEW.id OR a.existing_student_id=NEW.id))) BEGIN SELECT RAISE(ABORT,'An email address can register only once'); END;
CREATE TRIGGER student_contact_claim AFTER UPDATE OF email ON students WHEN trim(NEW.email)<>'' BEGIN INSERT OR IGNORE INTO registration_email_claims(email,student_id,claimed_at) VALUES(lower(trim(NEW.email)),NEW.id,strftime('%Y-%m-%dT%H:%M:%fZ','now')); END;
CREATE TRIGGER student_guardian_contact_unique BEFORE UPDATE OF guardian_email,contact_recipient ON students WHEN NEW.contact_recipient='guardian' AND trim(NEW.guardian_email)<>'' AND (lower(trim(NEW.guardian_email))<>lower(trim(OLD.guardian_email)) OR NEW.contact_recipient<>OLD.contact_recipient) AND EXISTS(SELECT 1 FROM registration_email_claims c WHERE c.email=lower(trim(NEW.guardian_email)) AND c.student_id IS NOT NEW.id AND NOT EXISTS(SELECT 1 FROM applications a WHERE a.id=c.application_id AND (a.student_id=NEW.id OR a.existing_student_id=NEW.id))) BEGIN SELECT RAISE(ABORT,'An email address can register only once'); END;
CREATE TRIGGER student_guardian_contact_claim AFTER UPDATE OF guardian_email,contact_recipient ON students WHEN NEW.contact_recipient='guardian' AND trim(NEW.guardian_email)<>'' BEGIN INSERT OR IGNORE INTO registration_email_claims(email,student_id,claimed_at) VALUES(lower(trim(NEW.guardian_email)),NEW.id,strftime('%Y-%m-%dT%H:%M:%fZ','now')); END;
